    intentScene: (situation, choice, change) => `- ${situation} -> ${choice} -> ${change}`,
    defaultReaderLegibility: 'Write so that the reader can hold on to the immediate goal of the scene, the surface meaning of the dialogue and the consequence of the choice without specialist knowledge.',
    defaultRegisterPolicy: 'Use precise observations, figures and technical terms in documents and operational situations, and prefer the natural wording the characters would actually use in everyday conversation and narration.',
